package com.gerenciadorrural.modules.farms.application;
import com.gerenciadorrural.modules.farms.domain.*; import com.gerenciadorrural.shared.tenancy.*; import org.junit.jupiter.api.Test; import org.springframework.dao.DataRetrievalFailureException; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class GetCurrentFarmProfileTest {@Test void executesRepositoryInsideTenantTransactionWithContextIds(){var executor=mock(TenantTransactionExecutor.class);var repo=mock(FarmProfileQueryRepository.class);var context=context();var expected=new FarmProfile(context.farmId(),context.tenantId(),"Fazenda","ACTIVE");when(executor.execute(eq(context),any(TenantTransactionalOperation.class))).thenAnswer(i->((TenantTransactionalOperation<?>)i.getArgument(1)).execute());when(repo.findCurrent(context.tenantId(),context.farmId())).thenReturn(Optional.of(expected));assertThat(new GetCurrentFarmProfile(executor,repo).execute(context)).isSameAs(expected);verify(repo).findCurrent(context.tenantId(),context.farmId());verify(executor).execute(eq(context),any(TenantTransactionalOperation.class));}
@Test void absenceIsGeneric(){var executor=mock(TenantTransactionExecutor.class);var repo=mock(FarmProfileQueryRepository.class);var context=context();when(executor.execute(eq(context),any(TenantTransactionalOperation.class))).thenAnswer(i->((TenantTransactionalOperation<?>)i.getArgument(1)).execute());when(repo.findCurrent(any(),any())).thenReturn(Optional.empty());assertThatThrownBy(()->new GetCurrentFarmProfile(executor,repo).execute(context)).isInstanceOf(FarmProfileNotAvailableException.class);}
@Test void technicalRepositoryFailureKeepsItsOriginalClassification(){var executor=mock(TenantTransactionExecutor.class);var repo=mock(FarmProfileQueryRepository.class);var context=context();var failure=new DataRetrievalFailureException("falha técnica");when(executor.execute(eq(context),any(TenantTransactionalOperation.class))).thenAnswer(i->((TenantTransactionalOperation<?>)i.getArgument(1)).execute());when(repo.findCurrent(context.tenantId(),context.farmId())).thenThrow(failure);assertThatThrownBy(()->new GetCurrentFarmProfile(executor,repo).execute(context)).isSameAs(failure);}
@Test void contextIsRequired(){assertThatNullPointerException().isThrownBy(()->new GetCurrentFarmProfile(mock(TenantTransactionExecutor.class),mock(FarmProfileQueryRepository.class)).execute(null));}private static TenantContext context(){return new TenantContext(new TenantId(UUID.randomUUID()),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"OWNER","ALL_FARMS");}}
